package ultra.downloads;
import android.app.Activity;import android.content.*;import android.database.MatrixCursor;import android.net.Uri;import android.provider.MediaStore;import java.util.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import org.robolectric.shadows.ShadowContentResolver;import app.revanced.extension.shared.utils.Utils;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33)
public class LocalAudioTest {
 Activity c;
 @Before public void setup()throws Exception{c=Robolectric.buildActivity(Activity.class).setup().get();Utils.testContext=c;org.robolectric.Shadows.shadowOf(c).grantPermissions(android.Manifest.permission.READ_MEDIA_AUDIO);Library.prefs(c).edit().clear().commit();Library.wiping=false;java.lang.reflect.Field f=Library.class.getDeclaredField("items");f.setAccessible(true);f.set(null,null);new java.io.File(c.getFilesDir(),"ultra_downloads_v1.json").delete();}
 @Test public void exactIdentityWinsAndAmbiguousMetadataDoesNotGuess(){ArrayList<Catalog.Track> tracks=new ArrayList<>();tracks.add(new Catalog.Track("abcdefghijk","Pal","Arijit Singh",""));assertEquals("0123456789_",LocalAudio.match("Pal [0123456789_].mp3","Different","Else",tracks));assertEquals("abcdefghijk",LocalAudio.match("Pal.mp3","PAL","Arijit Singh - Topic",tracks));tracks.add(new Catalog.Track("ABCDEFGHIJK","Pal","Arijit Singh",""));assertNull(LocalAudio.match("Pal.mp3","Pal","Arijit Singh",tracks));assertNull(LocalAudio.match("Pal.mp3","Pal","",tracks));}
 @Test public void playlistMembershipUsesIdsNotFuzzyTitles()throws Exception{PlaylistIndex.register("VLPLone","One");PlaylistIndex.register("VLPLtwo","Two");PlaylistIndex.record("PLone",Arrays.asList(new Catalog.Track("abcdefghijk","Pal","Singer","")),true);PlaylistIndex.record("PLtwo",Arrays.asList(new Catalog.Track("0123456789_","Pal","Other","")),true);assertEquals("One",PlaylistIndex.groups(c).get("PLone"));assertTrue(PlaylistIndex.members(c,"PLone").contains("abcdefghijk"));assertFalse(PlaylistIndex.members(c,"PLone").contains("0123456789_"));}
 @Test public void importedFileIsNeverDeletedByDownloader()throws Exception{Library.Item i=Library.add(c,"abcdefghijk","Existing");i.imported=true;java.io.File f=new java.io.File(c.getCacheDir(),"keep.mp3");new java.io.FileOutputStream(f).close();i.uri=f.toString();try{Storage.delete(c,i);fail();}catch(java.io.IOException expected){}assertTrue(f.exists());assertTrue(Library.Item.parse(i.json()).imported);}
 @Test public void mediaPermissionUsesAudioNotPhotos(){assertEquals(android.Manifest.permission.READ_MEDIA_AUDIO,LocalAudio.permission());assertTrue(LocalAudio.allowed(c));}
 @Test public void nativeMediaUriUsesExactImportedIdentity()throws Exception{String uri="content://media/external/audio/media/71";assertEquals(LocalAudio.localId(uri),LocalAudio.nativeUriId(uri));assertEquals(LocalAudio.localId(uri),LocalAudio.nativeUriId(uri.replace("/external/","/external_primary/")));Library.Item i=Library.add(c,"abcdefghijk","Existing");i.uri=uri;i.imported=true;assertEquals("abcdefghijk",LocalAudio.nativeUriId(uri));assertNull(LocalAudio.nativeUriId("PPAD"));assertNull(LocalAudio.nativeUriId("https://example.com/music"));assertNull(LocalAudio.nativeUriId("content://other/private/71"));}
 @Test public void localIdentityIsStableAndAccepted()throws Exception{String a=LocalAudio.localId("content://media/external/audio/media/71");assertEquals(a,LocalAudio.localId("content://media/external/audio/media/71"));assertTrue(a.matches("[A-Za-z0-9_-]{11}"));assertNotEquals(a,LocalAudio.localId("content://media/external/audio/media/72"));}
 @Test public void playlistNameIsReadEvenWithoutASongShelf()throws Exception{java.io.ByteArrayOutputStream title=new java.io.ByteArrayOutputStream(),name=new java.io.ByteArrayOutputStream(),id=new java.io.ByteArrayOutputStream(),header=new java.io.ByteArrayOutputStream(),root=new java.io.ByteArrayOutputStream();NativeSnapshotTest.field(title,1,"My playlist".getBytes("UTF-8"));NativeSnapshotTest.field(name,1,title.toByteArray());NativeSnapshotTest.field(id,1,"PLexample".getBytes("UTF-8"));NativeSnapshotTest.field(header,4,name.toByteArray());NativeSnapshotTest.field(header,5,id.toByteArray());NativeSnapshotTest.field(root,361650780,header.toByteArray());NativeSnapshot.playlistHeaders(root.toByteArray());assertEquals("My playlist",PlaylistIndex.read(c).getJSONObject("PLexample").getString("name"));}
 @Test public void reorderedCollaboratorsAndDuplicateDownloadSuffixMatchSafely(){List<Catalog.Track> tracks=Arrays.asList(new Catalog.Track("abcdefghijk","Pal","Arijit Singh, Shreya Ghoshal",""));assertEquals("abcdefghijk",LocalAudio.match("Pal.mp3","Pal","Shreya Ghoshal & Arijit Singh - Topic",tracks));assertEquals("abcdefghijk",LocalAudio.match("Pal [abcdefghijk] (1).mp3","","",tracks));assertEquals("abcdefghijk",LocalAudio.match("Pal-abcdefghijk.mp3","","",tracks));assertNull(LocalAudio.match("Pal.mp3","Pal (Remix)","Arijit Singh, Shreya Ghoshal",tracks));assertEquals("abcdefghijk",LocalAudio.match("Pal.mp3","Pal","Arijit Singh",tracks)); /* DL21: song name decides; a partial artist tag no longer blocks the match */}
 @Test public void countUsesUniqueDownloadedSongsNotMembershipSum()throws Exception{PlaylistIndex.roster(c,Arrays.asList(new Catalog.Playlist("VLPLone","One",""),new Catalog.Playlist("VLPLtwo","Two","")));PlaylistIndex.record("PLone",Arrays.asList(new Catalog.Track("abcdefghijk","Pal","Singer","")),true);PlaylistIndex.record("PLtwo",Arrays.asList(new Catalog.Track("abcdefghijk","Pal","Singer","")),true);Library.Item a=new Library.Item(),b=new Library.Item();a.id="abcdefghijk";b.id="0123456789_";a.state=b.state="done";assertArrayEquals(new int[]{1,1},LocalAudio.membership(c,Arrays.asList(a,b)));}
 @Test public void threeHundredFourteenFileIdentitiesMatchAcrossPlaylistsWithoutFuzzyGuessing()throws Exception{ArrayList<Catalog.Track> tracks=new ArrayList<>();ArrayList<Library.Item> files=new ArrayList<>();for(int n=0;n<314;n++){String id=String.format(java.util.Locale.US,"T%010d",n);String title="Song "+n,artist="Singer "+n;Catalog.Track t=new Catalog.Track(id,title,artist,"");tracks.add(t);Library.Item item=new Library.Item();item.id=id;item.state="done";files.add(item);}PlaylistIndex.roster(c,Arrays.asList(new Catalog.Playlist("VLPLone","One",""),new Catalog.Playlist("VLPLtwo","Two","")));PlaylistIndex.record("PLone",tracks.subList(0,200),true);PlaylistIndex.record("PLtwo",tracks.subList(150,314),true);for(int n=0;n<314;n++){Catalog.Track t=tracks.get(n);String filename=n%3==0?t.title+" ["+t.id+"].mp3":t.artist+" - "+t.title+".mp3";assertEquals(t.id,LocalAudio.match(filename,n%3==1?"":t.title,n%3==1?"":t.artist,tracks));}assertArrayEquals(new int[]{314,0},LocalAudio.membership(c,files));assertNull(LocalAudio.match("Singer 1 - Song 1 remix.mp3","","",tracks));}
}
